void hash_table_destroy(hashtable_t *ht) /* <=== hash_table_destroy */ 
{
	if (!ht) return;

	int i = 0;
	for (i = 0; i < 4096; i++) {
		if (ht->entries[i]) {
			hashentry_t* e = ht->entries[i];
			while (e) {
				if (ht->free_func) {
					ht->free_func(e->value);
				}
				hashentry_t* old = e;
				e = e->next;
				free(old);
			}
		}
	}
	free(ht);
}

static char *plist_utf16_to_utf8(uint16_t *unistr, long len, long *items_read, long *items_written) /* <=== plist_utf16_to_utf8 */ 
